def translate(s):
    return ''.join(codontab.get(s[i:i+3],'X') for i in range(0,len(s)-2,3))

def find_orfs(s, strand, minlen):
    out=[]
    for frame in range(3):
        aa=translate(s[frame:])
        i=0
        while i < len(aa):
            if aa[i]=='M':
                j=i
                while j<len(aa) and aa[j]!='*':
                    j+=1
                if (j-i)*3>=minlen:
                    out.append((frame+i*3, frame+j*3, strand, aa[i:j]))
                i=j+1
            else:
                i+=1
    return out

