def best_diagonal(A,B,minrun=20):
    nA=len(A); nB=len(B)
    best=[]
    # diag: A[i] vs B[i+d]
    for d in range(-nB+1, nA):
        i0=max(0,-d); j0=i0+d
        L=min(nA-i0, nB-j0)
        if L<minrun: continue
        # count identity
        run=0; mm=0; bestrun=0; beststart=None; start=0
        cur=0
        for t in range(L):
            if A[i0+t]==B[j0+t]:
                cur+=1
                if cur>bestrun:
                    bestrun=cur; beststart=(i0+t-cur+1, j0+t-cur+1)
            else:
                cur=0
        if bestrun>=minrun:
            best.append((bestrun,beststart,d))
    return sorted(best,reverse=True)

